def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    urgent_opp = 0
    rich_opp = 0
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('budget', 0) >= budget:
                rich_opp += 1
            if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
                urgent_opp += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bids.append(prev.get('bid', 0.0))

    if not alive:
        return float(min(budget, 12.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0.0

    supply_pressure = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if supply_pressure < 0:
        supply_pressure = 0.0
    if supply_pressure > 1:
        supply_pressure = 1.0

    danger = 0.0
    if hp <= 2:
        danger += 0.55
    elif hp <= 4:
        danger += 0.3
    if no_water >= 2:
        danger += 0.35
    elif no_water >= 1:
        danger += 0.18

    base = DAILY_SALARY * (0.34 + 0.28 * supply_pressure + danger)

    if highest_prev >= 150:
        reactive = min(95.0, avg_prev * 0.62 + 6.0)
    elif highest_prev >= 100:
        reactive = min(88.0, highest_prev * 0.78 + 3.0)
    elif highest_prev > 0:
        reactive = min(82.0, highest_prev + 2.5)
    else:
        reactive = DAILY_SALARY * 0.45

    bid = max(base, reactive)

    if supply >= 23 and hp >= 6 and no_water == 0:
        bid *= 0.72
    elif supply >= 20 and hp >= 5 and no_water == 0:
        bid *= 0.84

    if supply <= 17:
        bid += 8.0 + 2.0 * urgent_opp
    if hp <= 2 or no_water >= 2:
        bid = max(bid, DAILY_SALARY * 0.96)
    elif hp <= 4 or no_water >= 1:
        bid = max(bid, DAILY_SALARY * 0.78)

    if rich_opp >= 2 and supply <= 18:
        bid += 5.0

    if day >= 8 and budget > DAILY_SALARY * (11 - day):
        bid += 6.0

    reserve = 0.0
    if day <= 7:
        reserve = DAILY_SALARY * 0.35
    max_affordable = max(0.0, budget - reserve)
    if hp <= 3 or no_water >= 1 or day >= 9:
        max_affordable = budget

    bid = min(bid, max_affordable)
    bid = min(bid, budget)
    if bid < 0:
        bid = 0.0
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    bid = DAILY_SALARY * 0.5

    if my_status['hp'] <= 2:
        bid = DAILY_SALARY * 0.95
    elif my_status['hp'] <= 4:
        bid = DAILY_SALARY * 0.75
    elif my_status['hp'] >= 7:
        bid = DAILY_SALARY * 0.4

    estimated_total_demand = (num_alive_opponents + 1) * WATER_REQ
    current_supply = day_context['supply']

    if current_supply < estimated_total_demand:
        shortage_factor = (estimated_total_demand - current_supply) / estimated_total_demand
        bid *= (1 + shortage_factor * 0.6)
    elif current_supply >= estimated_total_demand + WATER_REQ * num_alive_opponents:
        bid *= 0.75

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        average_prev_bid = sum(yesterday_bids) / len(yesterday_bids)

        if highest_prev_bid >= DAILY_SALARY * 0.8:
            if my_status['hp'] <= 4:
                bid = max(bid, highest_prev_bid + (DAILY_SALARY * 0.1))
            else:
                bid = max(bid, highest_prev_bid + 5)
        elif average_prev_bid < DAILY_SALARY * 0.4:
            bid = min(bid, average_prev_bid + (DAILY_SALARY * 0.05))

    final_bid = max(1.0, bid)
    final_bid = min(final_bid, my_status['budget'])

    remaining_days = EPISODE_DAYS - day_context['day']
    if remaining_days <= 2 and my_status['hp'] <= 3:
        final_bid = min(my_status['budget'], DAILY_SALARY * 1.2)

    return float(final_bid)
